// CI-only synthetic encrypted P1G generated from EXISTING test helper.
// The generated bytes/digest are NOT committed and contain no user Save.
import {mkdir,writeFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {makeSyntheticP1gProfile,syntheticProfile} from '../helpers/p1g-fixture.mjs';
const root=syntheticProfile('DeviceType_Windows');
root.GameInfo.Version=626;
root.Player={};
for(let i=0;i<33;i++){
  root.Player['field_'+String(i).padStart(3,'0')]=
    i%2?{future:[true,null,{"🌿":"opaque"}]}:[1,2,{literal:"🍃"}];
}
root.World={WorldRoot:{Unknown:{preserve:true}},Clock:0};
root.Opaque.big='🌿'.repeat(140000);
const source=makeSyntheticP1gProfile(root);
const utf8=Buffer.from(JSON.stringify(root),'utf8');
await mkdir(new URL('./fixtures/',import.meta.url),{recursive:true});
await writeFile(new URL('./fixtures/synthetic626.p1g',import.meta.url),source);
await writeFile(new URL('./fixtures/expected.json',import.meta.url),
  JSON.stringify({decodedSha256:createHash('sha256').update(utf8).digest('hex'),
    decodedBytes:utf8.length,sourceBytes:source.length,playerFields:33,
    worldFields:2,syntheticOnly:true})+'\n');
console.log('STAGE_F_SYNTHETIC_FIXTURE_GENERATED_ONLY',{sourceBytes:source.length,decodedBytes:utf8.length});
